const source = $('Normalize Input').first().json;
const extractedText = String(source.extractedText || '').slice(0, 4000);
const multipleDocuments = /^--- Document 1 of \d+ ---/m.test(extractedText);
const documents = extractedText ? [extractedText] : [];

const toHeightBand = (mm) => {
  if (!Number.isFinite(mm) || mm <= 0) return null;
  const m = mm < 10 ? mm : mm / 1000;
  const bands = [0.4, 0.6, 0.8, 1, 1.2];
  let best = bands[0];
  let bestDiff = Math.abs(m - bands[0]);
  for (const b of bands) {
    const d = Math.abs(m - b);
    if (d < bestDiff) { best = b; bestDiff = d; }
  }
  return String(best);
};

const WALL_TYPES = [
  ['treated-timber', /treated timber|timber sleeper|sleepers?|hardwood/i],
  ['concrete-sleepers', /concrete sleeper/i],
  ['besser-block', /besser|block wall|masonry block/i],
  ['natural-stone', /natural stone|stone wall|sandstone|bluestone/i],
];

const LENGTH = [
  [/(\d+(?:\.\d+)?)\s*(?:lineal|linear)\s*(?:m\b|metres?|meters?)/i, (v) => v],
  [/(\d+(?:\.\d+)?)\s*(?:lm|l\.m\.)\b/i, (v) => v],
  [/(\d+(?:\.\d+)?)\s?L\b/, (v) => v],
  [/(\d+(?:\.\d+)?)\s*m\b(?=[^\n]{0,40}?(?:wall|retain|run\b))/i, (v) => (v >= 2 ? v : null)],
  [/(\d+(?:\.\d+)?)\s*(?:odd\s+|approx\.?\s+)?(?:metres?|meters?)\b/i, (v) => (v >= 2 ? v : null)],
];

const HEIGHT = [
  [/(\d+(?:\.\d+)?)\s?(?:mm|m)?\s?H\b/, (v) => (v < 10 ? Math.round(v * 1000) : Math.round(v))],
  [/\bH\s?[-:]?\s?(\d{3,4})\b/, (v) => Math.round(v)],
  [/(\d+(?:\.\d+)?)\s*(?:m\b|metres?|meters?|mm)?\s*(?:high|height|tall)\b/i, (v) => (v < 10 ? Math.round(v * 1000) : Math.round(v))],
];

const REMOVAL = [
  /\b(?:dispos\w*|remov\w*|demoli\w*|dismantl\w*)\b[^\.\n]{0,60}(?:wall|retain|sleeper|block)/gi,
  /\b(?:old|existing)\b[^\.\n]{0,30}?(?:wall|retain)/gi,
];
const NEGATED = /\b(?:no|not|excl\w*|without|nil)\b[^\.\n]{0,24}$/i;

// The job address, for the picker's benefit only. This is NOT checklist.suburb and never
// becomes it — the agent's own prompt already says the same thing ("never take it from a
// document as fact"). It only ever gives the picker a head start; Google's confirmation is
// still what fills checklist.suburb. Labelled lines first, since a contractor's letterhead
// is also an address and quoting it would send the job to the wrong side of the city.
const ADDRESS = [
  /^[^\n]{0,40}\b(?:property|site|job|install(?:ation)?)\s*address\s*[:\-–]\s*([^\n]+)$/im,
  /^[^\n]{0,10}\baddress\s*[:\-–]\s*([^\n]+)$/im,
  /^[^\n]{0,40}\b(?:suburb|location)\s*[:\-–]\s*([^\n]+)$/im,
  // Unlabelled last resort: a place written the way Australian addresses are written.
  /\b([A-Z][A-Za-z'’\-]+(?:\s+[A-Z][A-Za-z'’\-]+){0,3}\s+(?:VIC|NSW|QLD|SA|WA|TAS|NT|ACT)\s+\d{4})\b/,
];

// The contractor's own address is on the page too, usually at the top, and suggesting it would
// send the job to whichever suburb the builder trades from. A labelled line says whose address
// it is; an unlabelled one does not, so that line has to be clean of letterhead first.
const LETTERHEAD = /\b(?:abn|acn|pty|ltd|p\/l|phone|mobile|email|www\.|@|retaining|landscap(?:e|ing)|sleeper|constructions?|quotation|invoice|tax invoice)\b/i;

const readAddress = (text) => {
  for (let index = 0; index < ADDRESS.length; index += 1) {
    const match = text.match(ADDRESS[index]);
    if (!match) continue;
    const line = String(match[1] || '').trim().replace(/\s+/g, ' ').slice(0, 120);
    // A label with nothing useful after it ("Address: TBC") is not a location. A street number
    // or a state code is what makes it something Google can actually find.
    if (!line || !/\d|\b(?:VIC|NSW|QLD|SA|WA|TAS|NT|ACT)\b/i.test(line)) continue;
    // Only the last pattern is unlabelled, and only it needs the letterhead check — a line that
    // says "Property address" has already told us whose address it is.
    const unlabelled = index === ADDRESS.length - 1;
    if (unlabelled) {
      const lineStart = text.lastIndexOf('\n', match.index) + 1;
      let lineEnd = text.indexOf('\n', match.index);
      if (lineEnd === -1) lineEnd = text.length;
      if (LETTERHEAD.test(text.slice(lineStart, lineEnd))) continue;
    }
    return line;
  }
  return null;
};

const firstNumber = (text, patterns) => {
  for (const [pattern, refine] of patterns) {
    const match = text.match(pattern);
    if (!match) continue;
    const value = refine(Number(match[1]), match);
    if (Number.isFinite(value) && value > 0) return value;
  }
  return null;
};

const readDocument = (text) => {
  const facts = {};
  const wallType = WALL_TYPES.find(([, re]) => re.test(text));
  if (wallType) facts.wallType = wallType[0];

  const heightMm = firstNumber(text, HEIGHT);
  if (heightMm) facts.heightBand = toHeightBand(heightMm);

  const lengthMeters = firstNumber(text, LENGTH);
  if (lengthMeters) facts.lengthMeters = lengthMeters;

  for (const pattern of REMOVAL) {
    const hit = [...text.matchAll(pattern)].find(
      (m) => !NEGATED.test(text.slice(Math.max(0, m.index - 30), m.index)),
    );
    if (hit) { facts.removeOldWall = true; break; }
  }

  const totals = [...text.matchAll(/(sub[\s-]*)?total\b[^\n$]{0,16}\$\s?([\d,]+(?:\.\d{1,2})?)/gi)]
    .filter((m) => !m[1])
    .map((m) => Number(m[2].replace(/,/g, '')))
    .filter((v) => Number.isFinite(v) && v > 0);
  if (totals.length) facts.existingPrice = Math.max(...totals);

  return facts;
};

const singleDocument = documents.length === 1 && !multipleDocuments;
const docFacts = singleDocument ? readDocument(extractedText) : {};

// Read on the same terms, and kept out of docFacts on purpose: everything in there is merged
// straight into the checklist downstream, and this must never land in checklist.suburb.
const docSuburbHint = singleDocument ? readAddress(extractedText) : null;

// Handed over under the heading the agent's prompt already treats as settled fact. The address
// gets its own heading, worded the way the prompt's suburb rule already describes it, so the
// agent suggests it rather than treating it as an answer.
const docFactsBlock =
  (Object.keys(docFacts).length
    ? '\n\n--- Already established for this job, do NOT ask about these again ---\n' + JSON.stringify(docFacts)
    : '') +
  (docSuburbHint
    ? '\n\n--- Job address on the document (this is suggestedSuburb ONLY — checklist.suburb stays null until the customer picks it from the list) ---\n' +
      docSuburbHint
    : '');

return [{
  json: {
    message: source.message,
    sessionId: source.sessionId,
    extractedText,
    docFacts,
    docSuburbHint,
    docFactsBlock,
    extractionFailed: false,
  },
}];

const source = $('Normalize Extracted Text').first().json;
const sessionId = source.sessionId || null;

// Track whether this session has been seen before, so turn 1's opener message
// is never overwritten by the deterministic "ask next field" fallback below.
const staticData = $getWorkflowStaticData('node');
if (!staticData.seenSessions) staticData.seenSessions = {};
const isFirstTurn = sessionId ? !staticData.seenSessions[sessionId] : true;
if (sessionId) staticData.seenSessions[sessionId] = true;

let place = null;
try { place = JSON.parse($('Normalize Input').first().json.place || 'null'); } catch { place = null; }

const parsed = $input.first().json.output || {};
const FIELDS = ['suburb', 'wallType', 'lengthMeters', 'heightBand', 'removeOldWall', 'siteAccess'];

const ASK = {
  suburb: { message: 'Which suburb is the wall going in?', options: [] },
  wallType: {
    message: 'What type of retaining wall are you after?',
    options: [
      { label: 'Treated Timber', value: 'treated-timber' },
      { label: 'Concrete Sleepers', value: 'concrete-sleepers' },
      { label: 'Besser Block', value: 'besser-block' },
      { label: 'Natural Stone', value: 'natural-stone' },
    ],
  },
  lengthMeters: {
    message: 'How long is the wall?',
    options: [
      { label: '5m', value: 5 },
      { label: '10m', value: 10 },
      { label: '20m', value: 20 },
      { label: '30m', value: 30 },
      { label: 'Other', value: '__other__' },
    ],
  },
  heightBand: {
    message: 'What height are you after?',
    options: [
      { label: '0.4m', value: '0.4' },
      { label: '0.6m', value: '0.6' },
      { label: '0.8m', value: '0.8' },
      { label: '1.0m', value: '1' },
      { label: '1.2m', value: '1.2' },
    ],
  },
  removeOldWall: {
    message: 'Is there an old wall that needs removing?',
    options: [
      { label: 'Yes, please remove it', value: true },
      { label: 'No, starting fresh', value: false },
    ],
  },
  siteAccess: {
    message: "How's the access along the wall line?",
    options: [
      { label: 'Easy (flat, clear)', value: 'easy' },
      { label: 'Difficult (sloped, tight)', value: 'difficult' },
    ],
  },
};

let known = {};
try { known = JSON.parse($('Normalize Input').first().json.knownChecklist || '{}') || {}; } catch { known = {}; }
const docFacts = source.docFacts || {};

// The job address off the same document, kept separate from docFacts because it is never an
// answer — only what the picker opens with.
const docSuburbHint = source.docSuburbHint || null;

// Customers name their suburb in the same breath as everything else ("timber sleeper wall in
// Pakenham VIC 3810"). The model is asked to echo that into suggestedSuburb and usually does —
// and "usually" is what reaches the customer as an empty picker after they already typed the
// answer. Read here so it does not depend on the model remembering to.
const userMessage = String($('Normalize Input').first().json.message || '');
const MESSAGE_PLACE = [
  /\b([A-Z][A-Za-z'’\-]+(?:\s+[A-Z][A-Za-z'’\-]+){0,3},?\s+(?:VIC|NSW|QLD|SA|WA|TAS|NT|ACT)\s*,?\s*\d{4})\b/,
  /\b([A-Z][A-Za-z'’\-]+(?:\s+[A-Z][A-Za-z'’\-]+){0,2},?\s+(?:VIC|NSW|QLD|SA|WA|TAS|NT|ACT))\b/,
  /\b(?:in|at|near|around)\s+([A-Z][A-Za-z'’\-]{2,}(?:\s+[A-Z][A-Za-z'’\-]+){0,2})\b/,
];
const placeFromMessage = (text) => {
  for (const pattern of MESSAGE_PLACE) {
    const match = text.match(pattern);
    if (match && match[1]) return match[1].trim().replace(/\s+/g, ' ');
  }
  // A bare postcode only when the whole reply is one — otherwise a stray 4-digit number (like
  // a length typed alone) could be misread as a postcode.
  const bare = text.trim().match(/^(\d{4})$/);
  return bare ? bare[1] : null;
};

const merged = { ...(parsed.checklist || {}) };
for (const field of [...FIELDS, 'existingPrice']) {
  if ((merged[field] === null || merged[field] === undefined) && known[field] != null) merged[field] = known[field];
}
for (const field of [...FIELDS, 'existingPrice']) {
  if ((merged[field] === null || merged[field] === undefined) && docFacts[field] != null) merged[field] = docFacts[field];
}

const toNumber = (value) => {
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  if (value == null) return null;
  const text = String(value).replace(/,(?=\d{3}\b)/g, '');
  const match = text.match(/-?\d+(?:\.\d+)?/);
  if (!match) return null;
  const n = Number(match[0]);
  return Number.isFinite(n) ? n : null;
};

for (const field of ['lengthMeters', 'existingPrice']) {
  if (merged[field] != null) merged[field] = toNumber(merged[field]);
}

const snap = (value, allowed) => {
  if (typeof value !== 'string' || !value.trim()) return value;
  const lower = value.trim().toLowerCase();
  const exact = allowed.find((o) => o.toLowerCase() === lower);
  return exact || value;
};

merged.wallType = snap(merged.wallType, ['treated-timber', 'concrete-sleepers', 'besser-block', 'natural-stone']);
if (merged.heightBand != null) merged.heightBand = String(merged.heightBand);

// Picker confirmation is the suburb. Do not wait for the model to copy it.
if (place && (merged.suburb === null || merged.suburb === undefined || merged.suburb === '')) {
  merged.suburb = place.displayLabel || [place.suburb, place.state, place.postcode].filter(Boolean).join(', ') || merged.suburb;
}

// What to open the picker with, newest signal first: what they just typed, then the attached
// document, then whatever the model managed to suggest, then a name it wrote into the checklist
// without a picker behind it. None of these is an answer — the customer still taps the Google
// suggestion to confirm.
const suburbHint =
  placeFromMessage(userMessage) ||
  docSuburbHint ||
  (typeof parsed.suggestedSuburb === 'string' && parsed.suggestedSuburb.trim() ? parsed.suggestedSuburb.trim() : null) ||
  (typeof merged.suburb === 'string' && merged.suburb.trim() ? merged.suburb.trim() : null) ||
  null;

const checklist = Object.keys(merged).length > 0 ? merged : null;
const isMissing = (field) => {
  if (!checklist) return true;
  // A suburb nobody confirmed against Google is not established, whoever wrote it down. Without
  // a place there are no coordinates, and matching runs on distance — so a name on its own can
  // never produce a quote. Treating it as missing is what puts the picker on screen.
  if (field === 'suburb' && !place) return true;
  if (field === 'siteAccess' && checklist.removeOldWall === false) return false;
  return checklist[field] === null || checklist[field] === undefined;
};

const missing = FIELDS.filter(isMissing);
const nextField = missing[0];

let type = ['question', 'confirmation'].includes(parsed.type) ? parsed.type : 'message';
let message = typeof parsed.message === 'string' ? parsed.message.trim() : '';
let options = Array.isArray(parsed.options) ? parsed.options : [];

if (!message) {
  message = nextField ? ASK[nextField].message : 'Sorry, something went wrong — mind trying again?';
  if (nextField) {
    type = ASK[nextField].options.length ? 'question' : 'message';
    options = ASK[nextField].options;
  } else { type = 'message'; options = []; }
}

// The agent thinks it already has the suburb — it read the name off a message or a document —
// so it will never ask again of its own accord, and only asking puts the picker in front of the
// customer. Nothing else in the system can turn a name into a place.
if (checklist && checklist.suburb && !place) {
  type = 'message';
  message = ASK.suburb.message;
  options = [];
}

// Recapping after several answers and then carrying on with fields it never asked about is the
// model's favourite mistake — sometimes as a "confirmation" it isn't entitled to, sometimes just
// by narrating a handoff-shaped message while a field is still null. Any type is corrected here,
// not just "confirmation": a missing field always wins over whatever the model tried to say.
if (missing.length > 0 && !isFirstTurn) {
  type = ASK[nextField].options.length ? 'question' : 'message';
  message = ASK[nextField].message;
  options = ASK[nextField].options;
  if (nextField === 'suburb' && suburbHint) {
    message = 'I found ' + suburbHint + ' — confirm that suburb from the list?';
  }
}

// Which field the client should collect with something other than a plain text box. Only the
// suburb qualifies: a mistyped suburb doesn't fail loudly, it silently matches zero builders, so
// the client swaps its reply box for a Google-backed suburb picker and sends back a real place.
// Derived from the checklist, never from the model — 'suburb' is first in FIELDS, so it is the
// field due whenever it is still missing.
const asksForSuburb = /\bsuburbs?\b|\bpost ?code\b/i.test(message);
const expectsSuburb = nextField === 'suburb' && options.length === 0 && asksForSuburb;

return [{
  json: {
    sessionId,
    trade: 'retaining-wall',
    intent: checklist && checklist.existingPrice != null ? 'compare_quote' : 'new_quote',
    place,
    type,
    message,
    options,
    ...(expectsSuburb ? { expects: 'suburb' } : {}),
    // What the customer or their document called the place. Not an answer — a head start for
    // the picker, which still makes them confirm it against Google.
    ...(expectsSuburb && suburbHint ? { suggestedSuburb: suburbHint } : {}),
    checklistComplete: missing.length === 0 && !!parsed.checklistComplete,
    checklist,
    results: [],
    avgRatePerMeter: null,
  },
}];

const gate = $('Format Retaining Wall Result').first().json;
const checklist = gate.checklist || {};
const sessionId = gate.sessionId || null;
const intent = gate.intent;
const matcher = $input.first().json || {};

const fail = (message, reason) => [{
  json: { sessionId, trade: 'retaining-wall', intent, type: 'result', message, options: [], results: [],
    avgRatePerMeter: null, comparison: null, noMatchReason: reason, checklist, checklistComplete: true },
}];

if (matcher.matched === undefined) {
  return fail('Something went wrong finding businesses near you — mind trying again?', 'error');
}
if (matcher.matched !== true) {
  const reason = matcher.noMatchReason || 'area';
  const message = reason === 'place'
    ? "I couldn't place that suburb on the map. Could you pick it from the suggestions?"
    : reason === 'radius'
      ? 'There are retaining wall businesses in that suburb, but none travel far enough to reach you.'
      : 'No retaining wall business has registered that suburb yet. Try a nearby suburb?';
  return fail(message, reason);
}

const slug = (value) =>
  String(value == null ? '' : value).toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

const num = (value) => {
  const raw = value !== null && typeof value === 'object'
    ? (value.doubleValue ?? value.integerValue ?? value.stringValue ?? null) : value;
  const parsed = Number(raw);
  return Number.isFinite(parsed) ? parsed : null;
};

const wanted = slug(checklist.wallType);
const heightKey = checklist.heightBand != null ? String(checklist.heightBand) : null;
const lengthMetres = num(checklist.lengthMeters);
const GST_MULTIPLIER = 1.1;
const payable = (amount, gstInclusive) => (gstInclusive ? amount : Math.round(amount * GST_MULTIPLIER));

const quotes = [];
let blockedByType = 0;
let blockedByHeight = 0;

const covering = Array.isArray(matcher.businesses) ? matcher.businesses : [];
const pricingItems = Array.isArray(matcher.pricing) ? matcher.pricing : [];

for (let index = 0; index < pricingItems.length; index += 1) {
  const business = covering[index] || {};
  const pricing = pricingItems[index] || {};
  if (!business.uid || pricing.isComplete !== true) continue;

  const enabled = Array.isArray(pricing.enabledTypes) ? pricing.enabledTypes.map(slug) : [];
  if (!enabled.includes(wanted)) { blockedByType += 1; continue; }

  const rates = pricing.rates || {};
  const rateKey = Object.keys(rates).find((key) => slug(key) === wanted);
  const rate = rateKey && heightKey ? num((rates[rateKey] || {})[heightKey]) : null;
  if (rate === null) { blockedByHeight += 1; continue; }

  const removal = pricing.removal || {};
  const removalRate =
    checklist.removeOldWall === true && removal.offered === true
      ? (num(removal[checklist.siteAccess]) || 0) : 0;

  const gstInclusive = pricing.gstInclusive === true;
  const perMeter = rate + removalRate;
  const minimumCharge = payable(num(pricing.minimumCharge) || 0, gstInclusive);
  const total = Math.max(payable(Math.round(perMeter * (lengthMetres || 0)), gstInclusive), minimumCharge);

  const badges = [];
  badges.push(gstInclusive ? 'incl. GST' : 'incl. GST (added)');
  badges.push(business.distanceKm > 0 ? business.distanceKm + ' km away' : 'In your suburb');
  if (business.rating) badges.push(business.reviewCount ? business.rating + '★ (' + business.reviewCount + ')' : business.rating + '★');
  if (removalRate > 0) badges.push('Removal included');
  if (business.isAutoAcceptEnabled) badges.push('Instant accept');

  quotes.push({
    uid: business.uid,
    businessName: business.businessName,
    suburb: business.suburb,
    distanceKm: business.distanceKm,
    ratePerMeter: payable(rate, gstInclusive),
    autoAcceptsAi: business.autoAcceptsAi === true,
    currency: pricing.currency || 'AUD',
    projectTotalMin: total,
    projectTotalMax: total,
    estimatedTotal: total,
    badges,
  });
}

quotes.sort((a, b) => a.projectTotalMin - b.projectTotalMin);

const existingPrice = num(checklist.existingPrice);
const average = quotes.length > 0 ? Math.round(quotes.reduce((s, q) => s + q.projectTotalMin, 0) / quotes.length) : null;
const beating = existingPrice === null ? quotes : quotes.filter((q) => q.projectTotalMin < existingPrice);
const top = beating.slice(0, 3);

if (top.length === 0 && existingPrice !== null && quotes.length > 0) {
  const closest = quotes[0].projectTotalMin;
  return fail('Nobody covering your suburb came in under $' + existingPrice.toLocaleString() +
    '. The closest was $' + closest.toLocaleString() + '.', 'notCheaper');
}

if (top.length === 0) {
  const reason = blockedByType > 0 && blockedByHeight === 0 ? 'wallType' : blockedByHeight > 0 ? 'height' : 'pricing';
  const message = reason === 'wallType'
    ? 'The businesses near you do not offer that wall type yet. Want to try a different type?'
    : reason === 'height'
      ? 'Nobody near you publishes a rate at that height. Want to try a different height?'
      : 'I found businesses near you, but none have finished setting up their pricing yet.';
  return fail(message, reason);
}

const benchmark = existingPrice === null ? average : existingPrice;
const cheapest = top[0].projectTotalMin;

return [{
  json: {
    sessionId,
    trade: 'retaining-wall',
    intent,
    type: 'result',
    message: 'Here are the local businesses that cover your retaining wall job.',
    options: [],
    results: top.map((q) => ({
      businessId: q.uid,
      autoAcceptsAi: q.autoAcceptsAi,
      businessName: q.businessName,
      suburb: q.suburb,
      ratePerMeter: q.ratePerMeter,
      estimatedTotal: q.estimatedTotal,
      notes: q.badges.join(' · '),
    })),
    avgRatePerMeter: Math.round(top.reduce((s, q) => s + q.ratePerMeter, 0) / top.length),
    comparison: {
      potentialSavings: benchmark > cheapest ? benchmark - cheapest : null,
      marketAverage: average,
      totalQuotesScreened: matcher.totalCovering || covering.length,
      userExistingPrice: existingPrice,
      quotes: top.map((q) => ({
        businessId: q.uid,
        autoAcceptsAi: q.autoAcceptsAi,
        businessName: q.businessName,
        ratePerMeter: q.ratePerMeter,
        projectTotalMin: q.projectTotalMin,
        projectTotalMax: q.projectTotalMax,
        badges: q.badges,
        tag: q.projectTotalMin === cheapest ? 'BEST_VALUE' : null,
        savingsFromAverage: benchmark > q.projectTotalMin ? benchmark - q.projectTotalMin : null,
        suburb: q.suburb,
      })),
    },
    checklist,
    checklistComplete: true,
  },
}];
